
cc.Class({
    extends: require('LMSlots_Slots_Base'),

    properties: {
        _jpPanelList:[], // 奖池框框节点
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    //初始化
    Init:function(){
        this._topScript = cc.vv.gameData.GetTopScript();
        this._bottomScript = cc.vv.gameData.GetBottomScript();

        this._cfg = cc.vv.gameData.getGameCfg();
        this._col = 29;
        this._row = 1;

        this._node_bonus = cc.find("safe_node/bonus_game", this.node);
        this._node_bonus.active = false;

        this._bonus_slots = cc.find("slots", this._node_bonus);
        this._jpPanelList.push(cc.find("mini", this._bonus_slots));
        this._jpPanelList.push(cc.find("minor", this._bonus_slots));
        this._jpPanelList.push(cc.find("major", this._bonus_slots));
        this._jpPanelList.push(cc.find("maxi", this._bonus_slots));
        this._jpPanelList.push(cc.find("grand", this._bonus_slots));

        this._node_left = cc.find("node_left", this._bonus_slots);
        this._spine_collect = cc.find("safe_node/bonus_collect", this.node);
        this._spine_collect.active = false;

        this._topAniNode = cc.find("top_ani",this._bonus_slots);
        // this._spine_antiKuang = cc.find("JP_KongCaoTingPai",this._bonus_slots);

        this.createReels(this._col,this._row)

        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRecvMsgSubAction, this);
    },

    onDestroy(){
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRecvMsgSubAction, false, this);
    },

    //创建卷轴
    createReels:function(col,row){
        let node_reels = [];
        for (let i = 0; i < this._jpPanelList.length; i++){
            let reels = cc.find("reels", this._jpPanelList[i])
            if(reels){
                reels.children.forEach(reel=>{node_reels.push({node:reel, jpIdx:i+1})});
            }
        }

        for (let i = 0; i < node_reels.length; i++){
            let scp = node_reels[i].node.addComponent("Shakyamuni_BonusReels");
            scp.Init(i,row,this._topAniNode, node_reels[i].jpIdx);
            this._reels.push(scp);
        }
    },


    initSymbols(){
        let items = cc.vv.gameData.getEpicInfo().items;

        for (let i = 0; i < items.length; i++){
            let symbol = this.GetSymbolByIdx(i+1);
            if(items[i] == -1){
                symbol.ShowById(this.getBonusRandVal())
            } else {
                symbol.ShowById(3)
                symbol.setNum(items[i])
            }
        }
    },

    initKuangSpin(){
        for (let i = 0; i < this._jpPanelList.length; i++){
            let chuxian = cc.find("kuang/JP_ChuXian", this._jpPanelList[i]);
            let daiji = cc.find("kuang/JP_DaiJi", this._jpPanelList[i]);
            let shuaguang = cc.find("kuang/JP_ShuaGuang", this._jpPanelList[i]);
            let baoguang = cc.find("kuang/JP_BaoGuang", this._jpPanelList[i]);

            chuxian.active = false;
            daiji.active = this._epicInfo.jackpotList.includes(i+1);
            shuaguang.active = false;
            baoguang.active = false;
        }

        // this._spine_antiKuang.active = false;
    },


    playAntiAnim(bPlay, jpIdx){

        let chuxian = cc.find("kuang/JP_ChuXian", this._jpPanelList[jpIdx-1]);
        chuxian.active = bPlay;

        if(bPlay){
            let animList = ["Mini", "Minor", "Major", "Maxi", "Grand"];
            chuxian.getComponent(sp.Skeleton).setAnimation(0, "JP_ChuXian_"+animList[jpIdx-1]+"_Intro", false);
            chuxian.getComponent(sp.Skeleton).addAnimation(0, "JP_ChuXian_"+animList[jpIdx-1]+"_Loop", false);
        }
    },

    async enterBonusGame(isTri){
        return new Promise(async (success, failed)=> {
            Global.SlotsSoundMgr.playBgm('bgbgm');

            cc.vv.gameData.setIsBonusGame(true);
            this._bottomScript.SetWin(0);

            this._epicInfo = cc.vv.gameData.getEpicInfo();
            this._node_bonus.active = true;
            this.setRestCnt(this._epicInfo.restCnt);
            this.initSymbols();
            this.lockJackpot(this._epicInfo.jackpotValues);
            this.initKuangSpin();

            await this.playTriAnim(isTri);

            await cc.vv.gameData.awaitTime(1);
            this.reqSpin();

            this._bonusSuccess = success;
        });
    },

    reqSpin(){
        this._hintList = this._epicInfo.hintList;
        // this.SetReelStateInfo(this._epicInfo);
        this.StartMove(this._epicInfo);

        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.data = {rtype : 1}
        req.gameid = cc.vv.gameData.getGameId()
        cc.vv.NetManager.send(req,true);
    },

    async onRecvMsgSubAction(msg){
        if (msg.code === 200) {
            this._epicInfo = msg.data.epicInfo;
            this._gameInfo = this._epicInfo;
            cc.vv.gameData.setEpicInfo(this._epicInfo);
            this.SetSlotsResult(this._epicInfo.items)
        }
    },

    StartMove:function(data){
        this.setRestCnt(this._epicInfo.restCnt - 1);

        this._bStopRightnow = null
        this._gameInfo = null

        //top状态更新
        // this._topScript.StartMove()

        //清理数据
        // cc.vv.gameData.ClearOneRoundData()

        //每列转起来
        let reels = [];
        this._moveIdxs = [];
        for (let i = 0; i < data.items.length; i++){
            if(data.items[i] == -1){
                reels.push(this._reels[i]);
                this._moveIdxs.push(this._reels[i].GetReelIdx())
            }
        }
        this.MoveReels(reels)

        //设置停止时间
        //就是从开始旋转，如果多少秒会开始停止
        this._stopTime = this.GetStopTime()

        if(!this._bStopRightnow){

            this.SetReelStateInfo(data);

            let addT = this._reels[this._moveIdxs[0]].playAntiAnimation();
            this._stopTime += addT?1:0;
        }

    },

    SetSlotsResult:function(items){
        //把结果按卷轴结果整理
        let acRow = items.length / this._col
        let reelResults = []
        for(let i = 0;i < items.length; i++){
            let row = Math.floor(i / acRow)
            let col = i % this._col
            //配置中有没有这个元素
            // if(this._cfg.symbol[items[i]]){
                let res = {}
                if(items[i] == -1){
                    res.sid = this.getBonusRandVal() //符号id
                } else {
                    res.sid = 3;
                    res.data = {coin:items[i]};
                }
                if(!reelResults[col]) reelResults[col] = []
                reelResults[col].unshift(res)
            // }

        }

        for(let i = 0; i < this._reels.length; i++){
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    SetReelStateInfo(data){
        let hintResult = data.hintResult;   // 奖池
        let hintList = data.hintList;   // 位置

        for (let i = 0; i < hintList.length; i++){
            let reelIdx = hintList[i]-1;
            this._reels[reelIdx].setIsAnt(true);
        }
    },

    DoCheckReelAnti:function(colIdx){
        if(!this._bStopRightnow){
            let isPlayAnit = false
            for(let i = 0; i < this._reels.length; i++){
                let idx = this._reels[i].GetReelIdx()

                if(this._moveIdxs.indexOf(i) == this._moveIdxs.indexOf(colIdx)+1){
                    isPlayAnit = this._reels[idx].playAntiAnimation()
                }

                if(idx > colIdx && isPlayAnit){
                    let nAddSpeedTime = cc.vv.gameData.getGameCfg().AddAntiTime || 1
                    this._reels[idx].AddDelayTime(nAddSpeedTime)
                }
            }
        }
    },

    //单列停止
    //colIdx:0开始
    //回弹动作执行之前的停止时机
    OnReelSpinEnd:function(colIdx){
        let jpIdx = this._reels[colIdx].getJpIdx();
        if(this._epicInfo.jackpotList.includes(jpIdx)){
            Global.SlotsSoundMgr.playEffect("jpawards");

            let jpList = ["Mini","Minor","Major","Maxi","Grand"];
            let baoguang = cc.find("kuang/JP_BaoGuang", this._jpPanelList[jpIdx-1]);
            baoguang.active = true;
            baoguang.getComponent(sp.Skeleton).setAnimation(0, "JP_BaoGuang_"+jpList[jpIdx-1],false);

            let daiji = cc.find("kuang/JP_DaiJi", this._jpPanelList[jpIdx-1]);
            daiji.active = true;
        }
    },

    OnSpinEnd(){
        if(this._gameInfo.isEnd){   // 结束
            this.playGameResult();
        } else {
            this.onSpinEndAction();
        }
    },

    async playGameResult(){
        if(this._epicInfo.jackpotList.length > 0){
            await this.playWinJpAnim();
        }

        await this.flyAllItems();

        let totalWin = this._epicInfo.winCoin
        await cc.vv.gameData.getPopupScript().endBonusGame(totalWin);

        cc.vv.gameData.getPopupScript().playXiongmaoQpAnim();

        await cc.vv.gameData.awaitTime(3.2);
        this._node_bonus.active = false;
        this.resetJackpot();
        cc.vv.gameData.setIsBonusGame(false);
        Global.SlotsSoundMgr.stopBgm();

        cc.vv.gameData.AddCoin(totalWin);
        await new Promise((sucess, failed)=>{
            this.ShowBottomWin(totalWin,totalWin,true,sucess)
        });

        if(this._bonusSuccess){
            this._bonusSuccess();
            this._bonusSuccess = null;
        }
    },

    async onSpinEndAction(){
        this.setRestCnt(this._epicInfo.restCnt, this._epicInfo.restCnt==3);

        await cc.vv.gameData.awaitTime(1);
        this.reqSpin();
    },


    getBonusRandVal(){
        let cfg = cc.vv.gameData.getGameCfg()
        let randIdx = Global.random(1,cfg.randomBonusSymbols.length)
        return cfg.randomBonusSymbols[randIdx-1]
    },

    //每列停止时间间隔 = 每列的停止间隔 + 每列的回弹时间
    //reelIdx:0开始
    GetReelStopInter:function(reelIdx){
        let nIter = this._cfg.bonusReelStopInter || 0.6
        return reelIdx*nIter
    },


    // 触发动画
    playTriAnim(isTri){
        return new Promise(async (success, failed)=> {
            if(isTri){

                for (let i = 0; i < this._jpPanelList.length; i++) {
                    let pos_s = cc.find("pos_4", this._bonus_slots).position;
                    let pos_e = cc.find("pos_" + (i + 1), this._bonus_slots).position;

                    this.showJpTit(this._jpPanelList[i], false);
                    if (i < 3) {
                        this._jpPanelList[i].position = pos_s
                    } else {
                        this._jpPanelList[i].position = pos_e
                    }

                    cc.tween(this._jpPanelList[i])
                        .delay(i * 0.2)
                        .to(1 - i * 0.2, {position: pos_e})
                        .delay(i * 0.3)
                        .parallel(
                            cc.tween().to(0.3, {scale: 1.2}).to(0.2, {scale: 1}),
                            cc.tween().call(() => {
                                this.showJpTit(this._jpPanelList[i], true, true);
                            })
                        )
                        .start()
                }

                await cc.vv.gameData.awaitTime(1)
                Global.SlotsSoundMgr.playEffect("bgreelup");
                await cc.vv.gameData.awaitTime(2)

            } else {
                for (let i = 0; i < this._jpPanelList.length; i++){
                    this._jpPanelList[i].position = cc.find("pos_"+(i+1), this._bonus_slots).position;
                    this.showJpTit(this._jpPanelList[i], true);
                }
            }

            success();
        });
    },

    /**
     *
     * @param node 父节点
     * @param bShow 显隐
     * @param bPlay 弹出动画
     * @param animName spine动画
     */
    showJpTit(node, bShow, bPlay, animName){
        let jp_1 = cc.find("jp_1", node);
        let jp_2 = cc.find("jp_2", node);

        jp_1.active = bShow;
        jp_2.active = bShow;

        if(bPlay){
            jp_1.setScale(0);
            jp_2.setScale(0);

            cc.tween(jp_1).to(0.5, {scale:1}).start()
            cc.tween(jp_2).to(0.5, {scale:1}).start()
        }

        if(animName){
            let animList = ["Mini","Minor","Major","Maxi","Grand"]
            jp_1.getComponent(sp.Skeleton).setAnimation(0, "JP_ShuZiDaiJi_"+animName+"EN")
            jp_2.getComponent(sp.Skeleton).setAnimation(0, "JP_ShuZiDaiJi_"+animName+"EN")
        }
    },

    setRestCnt(curT, bAdd){
        let spr_lbl = cc.find("spr_lbl", this._node_left);
        spr_lbl.getComponent("ImgSwitchCmp").setIndex(curT);

        let spine = cc.find("spine", this._node_left);
        if(bAdd){
            spine.active = true;
            spine.getComponent(sp.Skeleton).setAnimation(0, "collect_glow", false);
            Global.SlotsSoundMgr.playEffect("bgcountback3");
        } else {
            spine.active = false;
        }
    },



    // 赢奖池
    async playWinJpAnim(){
        let winList = this._epicInfo.jackpotList;
        winList.sort((a,b)=>{return a-b});

        let total = this._bottomScript.getCurrentWin();
        for (let i = 0; i < winList.length; i++){
            let winCoin = this._epicInfo.jackpotValues[winList[i]-1];
            await cc.vv.gameData.getPopupScript().winJpAnim(winCoin, winList[i])
            total += winCoin;
            this._bottomScript.SetWin(total);
        }
    },

    flyAllItems(){
        return new Promise(async (success, failed)=> {
            let items = this._epicInfo.items;
            let total = this._bottomScript.getCurrentWin();
            for (let i = 0; i < items.length; i++){
                if(items[i] > 0){
                    let symbol = this.GetSymbolByIdx(i+1);

                    let fromPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                    let endNode = cc.find("safe_node/LMSlots_Bottom/winBg/lbl_winNum_nor", this.node);
                    let toPos = endNode.convertToWorldSpaceAR(cc.v2(0, 0));

                    // symbol.setSymbolMask(true);
                    Global.SlotsSoundMgr.playEffect("");
                    await this.flyItem(fromPos, toPos)
                    // this.showItem(i+1, true,items[i]);
                    total += items[i];
                    this._bottomScript.SetWin(total);

                    await cc.vv.gameData.awaitTime(0.5);
                }
            }

            success();
        })
    },

    flyItem(fromPos, toPos){
        return new Promise(async (success, failed)=> {
            Global.SlotsSoundMgr.playEffect("bgcollect");

            let from = this._spine_collect.parent.convertToNodeSpaceAR(fromPos);
            let to = this._spine_collect.parent.convertToNodeSpaceAR(toPos);

            //设置缩放和角度
            let v = cc.v2(to.x, to.y).sub(cc.v2(from.x, from.y));
            let length = v.mag();
            let angle = v.signAngle(cc.v2(1, 0));
            this._spine_collect.active = true;
            this._spine_collect.position = from;
            this._spine_collect.angle = -angle * cc.macro.DEG +90;
            this._spine_collect.scaleY = length / 500;
            this._spine_collect.scaleX = Math.min(1, length / 500);

            //播放动画
            this._spine_collect.getComponent(sp.Skeleton).setAnimation(0,"path_lizi1", false);

            await cc.vv.gameData.awaitTime(0.5);
            success();
        });
    },


    //奖池锁定(停止滚动)
    lockJackpot(poolList){
        let prizepool = cc.find('Canvas/safe_node/LMSlots_PrizePool_1').getComponent("LMSlots_PrizePool_Base");
        prizepool.PausePool([{prizeType:0,pauseNum:poolList[0]},{prizeType:1,pauseNum:poolList[1]},
            {prizeType:2,pauseNum:poolList[2]},{prizeType:3,pauseNum:poolList[3]},{prizeType:4,pauseNum:poolList[4]}]);
    },

    //复位奖池(继续滚动)
    resetJackpot(){
        let prizepool = cc.find('Canvas/safe_node/LMSlots_PrizePool_1').getComponent("LMSlots_PrizePool_Base");
        prizepool.ResumePausePool();
    },

    // update (dt) {},
});
