
cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {
        _jpIdx:0,   // 列所在奖池
        _isAnt:false,   // 是否播放加速动画
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init(idx,nCount,node, jpIdx){
        this._holderNode = cc.find("mask/holder",this.node)
        this._holderOrigPosY = this._holderNode.position.y

        this.setJpIdx(jpIdx);
        this._super(idx,nCount,node);

        for (let i = 0; i < this._symbols.length; i++){
            this._symbols[i].setType(2)
        }
    },

    setJpIdx(val){
        this._jpIdx = val;
    },
    getJpIdx(){
        return this._jpIdx;
    },

    StartMove(){
        this._super()

        this.setIsAnt(false);
    },

    //列停止
    OnReelSpinEnd:function(){
        this._reelState = []
        let slots = cc.vv.gameData.getBonusSlotsScript()
        slots.OnReelSpinEnd(this._reelIdx)

        //不能判断，停下来的列等于总共的列，因为有时候只旋转了3列
        //停下来的列以及等于最后一列旋转的列，
        //说明整个列已经停止
        let lastReelStopIdx = slots.GetLastStopReelIdx()
        if(this._reelIdx == lastReelStopIdx){
            //所有列都停止了
            slots.OnSpinEnd()
        }
    },

    //已经准备开始停止了
    //即：开始设置结果，已经进入了停止周期，stoptime变负的那一刻
    //执行在回弹之前
    ReadyToStop:function(){
        if(!this._bNotifyReadyStop){
            this._bNotifyReadyStop = true
            let slots = cc.vv.gameData.getBonusSlotsScript()
            slots.OnReelReadyToStop(this._reelIdx)
        }
    },

    //列回弹动作之前
    OnReelBounsActionBefore:function(){
        let slots = cc.vv.gameData.getBonusSlotsScript()
        slots.OnReelBounsActionBefore(this._reelIdx)
        if(this._originResult){
            for(let i = 0; i < this._originResult.length; i++){
                this._symbols[i].StopMoveBefore();
            }
        }

    },

    //回弹动作最低点
    OnReelBounsActionDeep:function(){
        // cc.vv.gameData.getBonusSlotsScript().playAntiAnim(false, this._reelIdx, this._jpIdx);

        this.ShowAntiEffect(false)
        this.playReelStop()
        let slots = cc.vv.gameData.getBonusSlotsScript()
        slots.OnReelBounsActionDeep(this._reelIdx)
        if(this._originResult){
            for(let i = 0; i < this._originResult.length; i++){
                this._symbols[i].StopMoveDeep();
            }
        }

    },

    //列回弹动作完成之后
    OnReelBounsActionEnd:function(){
        let slots = cc.vv.gameData.getBonusSlotsScript()
        slots.OnReelBounsActionEnd(this._reelIdx)
        if(this._originResult){
            for(let i = 0; i < this._originResult.length; i++){
                this._symbols[i].StopMoveEnd();
            }
        }
        else{
            cc.log('回弹结束，数据已经被清空了')
        }

        this.OnReelSpinEnd()
    },

    setIsAnt(val){
        this._isAnt = val;
    },

    playReelStop(){
        let stopEff = this._symbols[0].GetShowId() == 3 ? "bgreelbgsctr" : "reelstop";

        Global.SlotsSoundMgr.playEffect(stopEff);
    },

    //播放加速动画
    playAntiAnimation(){
        if(this._isAnt){
            this.ShowAntiEffect(true)
            // cc.vv.gameData.getBonusSlotsScript().playAntiAnim(true, this._reelIdx, this._jpIdx);
        }
        return this._isAnt
    },

    //加速框的显示
    ShowAntiEffect:function(bShow,name){
        let node = cc.find("node_anti", this.node);
        if(node){
            if(bShow){
                node.active = true;
                cc.vv.gameData.getBonusSlotsScript().playAntiAnim(true, this._jpIdx);
                Global.SlotsSoundMgr.playEffect("jpchuxian");
            } else {
                if(node.active){
                    node.active = false;
                    // 既然不是循环的播放，就不需要主动停止
                    // 点立即停止的时候需要停止加速音效
                    if(this._stopRightNow){
                        cc.vv.AudioManager.stopEffectByName("jpchuxian");
                    }
                    cc.vv.gameData.getBonusSlotsScript().playAntiAnim(false, this._jpIdx);
                }
            }
        }

    },

    // update (dt) {},
});
