    winJpAnim(winCoin, jpIdx){
        return new Promise(async (success, failed)=> {
            Global.SlotsSoundMgr.playEffect("jpbgm");

            this._node_popup.active = true;
            this._node_win_jp.active = true;

            let bg = cc.find("bg", this._node_win_jp);
            let title = cc.find("title", this._node_win_jp);
            let kuang = cc.find("kuang", this._node_win_jp);
            let btn = cc.find("btn", this._node_win_jp);
            btn.getComponent(cc.Button).interactable = false;

            cc.find("kuang/lbl_win", this._node_win_jp).getComponent(cc.Label).string = Global.FormatNumToComma(winCoin);

            bg.getComponent(sp.Skeleton).setAnimation(0,"intro",false);
            bg.getComponent(sp.Skeleton).addAnimation(0,"idle",true);
            let jpNameList = ["Mini_EN","Minor_EN","Major_EN","Maxi_EN","Grand_EN"];
            title.getComponent(sp.Skeleton).setAnimation(0,jpNameList[jpIdx-1],true);

            title.opacity = 0;
            kuang.opacity = 0;
            btn.opacity = 0;
            title.position = cc.v2(title.x, title.y - 40);
            kuang.position = cc.v2(kuang.x, kuang.y - 40);
            btn.position = cc.v2(btn.x, btn.y - 40);

            await cc.vv.gameData.awaitTime(0.5);
            let changeTime = 0.4;
            let delayTime = 0.2;
            cc.tween(title).to(changeTime, {position:cc.v2(title.x, title.y+40), opacity:255}).start()
            cc.tween(kuang).delay(delayTime*2).to(changeTime, {position:cc.v2(kuang.x, kuang.y+40), opacity:255}).start()
            cc.tween(btn).delay(delayTime*3).to(changeTime, {position:cc.v2(btn.x, btn.y+40), opacity:255}).start()
            await cc.vv.gameData.awaitTime(delayTime*3+changeTime);

            btn.off("click");
            btn.getComponent(cc.Button).interactable = true;
            let self = this;
            let clickFunc = async()=>{
                Global.SlotsSoundMgr.playEffect("button");
                btn.getComponent(cc.Button).interactable = false;
                bg.getComponent(sp.Skeleton).addAnimation(0,"end",false);
                cc.tween(title).to(changeTime,{opacity:0},{easing:"backIn"}).start()
                cc.tween(kuang).delay(delayTime*2).to(changeTime,{opacity:0},{easing:"backIn"}).start()
                cc.tween(btn).delay(delayTime*3).to(changeTime,{opacity:0},{easing:"backIn"}).start()
                await cc.vv.gameData.awaitTime(delayTime*3+changeTime);

                self._node_popup.active = false;
                self._node_win_jp.active = false;

                success();
            };
            cc.vv.gameData.checkAutoPlay(btn, clickFunc)
            btn.on("click", async()=> {
                btn.stopAllActions();
                clickFunc();
            });
        });
    },

    playTaijiQpAnim(){
        Global.SlotsSoundMgr.playEffect("fgtransition");

        this._qp_taiji.active = true;
        this._qp_taiji.getComponent(sp.Skeleton).setAnimation(0, "guochang", false);
        this._qp_taiji.getComponent(sp.Skeleton).setCompleteListener(()=>{
            this._qp_taiji.getComponent(sp.Skeleton).setCompleteListener(null);
            this._qp_taiji.active = false;
        })
    },

    playXiongmaoQpAnim(){
        Global.SlotsSoundMgr.playEffect("bgtransition");

        this._qp_xiongmao.active = true;
        this._qp_xiongmao.getComponent(sp.Skeleton).setAnimation(0, "idle2", false);
        this._qp_xiongmao.getComponent(sp.Skeleton).setCompleteListener(()=>{
            this._qp_xiongmao.getComponent(sp.Skeleton).setCompleteListener(null);
            this._qp_xiongmao.active = false;
        })
    },

