
cc.Class({
    extends: cc.Component,

    properties: {
        _itemSpList:[],
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init(){
        this._node_collect = cc.find("safe_node/slots/node_collect", this.node);

        for (let i = 1; i <= 10; i++){
            this._itemSpList[i]=cc.find("list/item"+i, this._node_collect).getComponent(sp.Skeleton);
        }

        this._spine_jiesuo = cc.find("spine_jiesuo", this._node_collect);
        this._spine_shangsuo = cc.find("spine_shangsuo", this._node_collect);

        this._btn_click = cc.find("btn_click", this._node_collect);
        Global.btnClickEvent(this._btn_click, this.onClickSjt, this);

        this.initItems();
        this.initSjtState();
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,this.onEventTotalbetUpdated,this)// 押注额改变

    },

    setCollectState(bShow){
        this._node_collect.active = bShow;
    },

    initItems(){
        let curCnt = cc.vv.gameData.getBonusTrail().count;

        for (let i = 1; i < this._itemSpList.length; i++){
            let aniName = curCnt >= i ? "liang" : "an";
            this._itemSpList[i].setAnimation(0, aniName, true);
        }
    },

    addItem(){
        return new Promise(async (success, failed)=> {
            if(this._isLock){
                success();
                return
            }
            let curCnt = cc.vv.gameData.getBonusTrail().count;
            let addEff = curCnt == 10 ? "collectSuper" : "collect"
            Global.SlotsSoundMgr.playEffect(addEff);

            let aniName = curCnt == 10 ? "taiji" : "jinbi";
            let entry = this._itemSpList[curCnt].setAnimation(0, aniName, false);
            this._itemSpList[curCnt].addAnimation(0, "liang", true);
            this._itemSpList[curCnt].setTrackCompleteListener(entry, ()=>{
                this._itemSpList[curCnt].setTrackCompleteListener(entry, null);
                success();
            })
        });
    },

    fullAnim(){
        return new Promise(async (success, failed)=> {
            Global.SlotsSoundMgr.playEffect();



        });
    },

    initSjtState(){
        let curBet = cc.vv.gameData.GetBetIdx();
        let needBet = cc.vv.gameData.getNeedBet();

        this._isLock = curBet < needBet;
        if(this._isLock){
            this._spine_shangsuo.active = true;
            this._spine_shangsuo.getComponent(sp.Skeleton).setAnimation(0,"BetUp_ShangSuo_Loop",true);
        } else {
            this._spine_shangsuo.active = false;
        }

        this._spine_jiesuo.active = false;
    },

    // 点击收集条
    onClickSjt(){
        if (!cc.vv.gameData.GetBottomScript().GetSpinBtnState()) return;
        if (cc.vv.gameData.GetAutoModelTime() > 0) return;
        // if (cc.vv.gameData.isFreeGame()) return;
        // if (cc.vv.gameData.isBonusGame()) return;

        let curBet = cc.vv.gameData.GetBetIdx();
        let needBet = cc.vv.gameData.getNeedBet();
        if(this._isLock && needBet >= curBet){
            cc.vv.gameData.GetBottomScript().SetBetIdx(needBet);
        }
    },

    // 押注额改变
    onEventTotalbetUpdated(){
        let curBet = cc.vv.gameData.GetBetIdx();
        let needBet = cc.vv.gameData.getNeedBet();

        if(this._isLock && curBet >= needBet) { // 解锁
            Global.SlotsSoundMgr.playEffect("unlock");
            this._isLock = false;

            this._spine_shangsuo.active = false;
            this._spine_jiesuo.active = true;
            this._spine_jiesuo.getComponent(sp.Skeleton).setAnimation(0,"JDT_JieSuo",false);
            this._spine_jiesuo.getComponent(sp.Skeleton).setCompleteListener(()=>{this._spine_jiesuo.active = false;})

        } else if(!this._isLock && curBet < needBet){   // 上锁
            Global.SlotsSoundMgr.playEffect("lock");
            this._isLock = true;

            this._spine_jiesuo.active = false;
            this._spine_shangsuo.active = true;

            this._spine_shangsuo.getComponent(sp.Skeleton).setAnimation(0,"BetUp_ShangSuo_Intro",false);
            this._spine_shangsuo.getComponent(sp.Skeleton).addAnimation(0,"BetUp_ShangSuo_Loop",true);
        }
    },

    // update (dt) {},
});
