
cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        _type:1,    //1-normal  2-bonus
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    setType(val){
        this._type = val;
    },

    //显示symbole
    ShowById:function(id,data) {
        this._super(id, data);

        this.setNum();

        if(this._type && this._type == 2){  // bonus
            this.setMaskVisible(true);
        }
    },

    setMaskVisible(bMask) {
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[this._id] && cfg.symbol[this._id].node){
            let showNode = cc.find(cfg.symbol[this._id].node,this.node)
            if (bMask && cfg.symbol[this._id].isMask) {
                showNode.color = new cc.Color(100, 100, 100);
            }
            else {
                showNode.color = cc.Color.WHITE;
            }
        }
    },

    setNum(val){
        let lbl = cc.find("lbl", this.node);

        if(val){
            lbl.active = true;
            lbl.getComponent(cc.Label).string =  Global.formatNumShort(val,1);
        } else {
            lbl.active = false;
            lbl.getComponent(cc.Label).string = "";
            lbl.stopAllActions();
            lbl.setScale(1);
        }

        return lbl;
    },

    //触发动画
    //触发了才播放的。比如已经3个scatter已经触发了免费。这个和中奖的还不一样
    playTriggerAnimation(){
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].trigger_ani){
            this._state = "trigger";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            if(cfg.symbol[id].trigger_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].trigger_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                isPlay = true
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].trigger_ani.name,true)
                }
            }
        }
        return isPlay
    },

    //停止最低点之后
    StopMoveDeep(){
        let id = this._id;
        if(id == 3 && this._data){    // bonus
            this.playBonusStopAnim();
        }

    },

    // bonus图标停止动画
    playBonusStopAnim(){
        let id = this._id;
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node){
            this._state = "bonusStop";
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true

            if(this._data.spCard){
                if(cfg.symbol[id].stop_logoAni.name != ""){
                    this.node.zIndex = cfg.symbol[id].stop_logoAni.zIndex - this._symbolIdx  + this._reelIdx*10;
                    let nodeSp = this._showNode.getComponent(sp.Skeleton)
                    if(nodeSp){
                        nodeSp.setAnimation(0,cfg.symbol[id].stop_logoAni.name,false)
                    }
                }

            }else {
                if(cfg.symbol[id].stop_numAni.name != ""){
                    this.node.zIndex = cfg.symbol[id].stop_numAni.zIndex - this._symbolIdx  + this._reelIdx*10;
                    let nodeSp = this._showNode.getComponent(sp.Skeleton)
                    if(nodeSp){
                        nodeSp.setAnimation(0,cfg.symbol[id].stop_numAni.name,false)
                    }
                }

                if(this._data.coin > 0){
                    let lbl = this.setNum(this._data.coin);
                    lbl.scaleX = 0;
                    cc.tween(lbl)
                        .delay(0.4)
                        .to(0.3,{scaleX:1})
                        .to(0.2,{scale:1.3})
                        .to(0.2,{scale:1})
                        .start();
                }
            }
        }
    },

    //
    /*async playOpenDoorAnim(card){
        let id = this._id;
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node){
            if(cfg.symbol[id].open_ani.name != ""){
                if(this._showNode){
                    this._showNode.active = false
                }

                let node = cc.find(cfg.symbol[id].win_node,this.node)
                node.active = true;

                let nodeSp = node.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].open_ani.name,false)
                }

                await cc.vv.gameData.awaitTime(1);

                this.ShowById(card)
            }
        }
    },*/

});
